(function(root){
'use strict';
function groups(text,file='unit.ini'){const lines=String(text).split('\n'),out=[];let triple=false,section='',ordinal={};for(let i=0;i<lines.length;i++){const line=lines[i];if(!triple&&/^\s*[#;]/.test(line)){let end=i+1;while(end<lines.length&&/^\s*[#;]/.test(lines[end]))end++;let next=end;while(next<lines.length&&!lines[next].trim())next++;const target=lines[next]?.match(/^\s*\[([^\]]+)\]/)?.[1]||section+':'+(lines[next]?.match(/^\s*([^:=]+)[:=]/)?.[1]?.trim()||'end');const base=file+'|'+target;for(let j=i;j<end;j++){const comment=lines[j].replace(/^\s*[#;]\s?/,''),id=base+'|'+comment;ordinal[id]=(ordinal[id]||0)+1;out.push({id:id+'|'+ordinal[id],line:j,text:comment,section:target,file})}i=end-1;continue}if(!triple)section=line.match(/^\s*\[([^\]]+)\]/)?.[1]||section;if((line.match(/"""/g)||[]).length%2)triple=!triple}return out}
function apply(text,file,policy={mode:'all'}){if(policy.mode==='all')return text;const keep=new Set(policy.selected||[]),remove=new Set(groups(text,file).filter(x=>policy.mode==='none'||!keep.has(x.id)).map(x=>x.line));return text.split('\n').filter((_,i)=>!remove.has(i)).join('\n')}
const core={groups,apply};root.RWComments=core;if(typeof module!=='undefined')module.exports=core;if(typeof document==='undefined')return;
const key='rwlab-export-comments-v1',L=(zh,en)=>root.RWI18n?.lang==='en'?en:zh,E=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function settings(){try{return JSON.parse(localStorage.getItem(key))||{mode:'all',selected:[],remember:false}}catch{return {mode:'all',selected:[],remember:false}}}
async function choose(files,force=false){const pref=settings();if(pref.remember&&!force)return pref;return new Promise(resolve=>{const entries=files.flatMap(f=>groups(f.data,f.name)),dialog=document.createElement('dialog');dialog.className='export-dialog';dialog.innerHTML=`<div class="dialog-head"><span class="eyebrow">EXPORT / COMMENTS</span><button class="icon-btn" data-cancel aria-label="${L('关闭','Close')}">×</button></div><h2>${L('导出时保留哪些注释','Which comments should be included?')}</h2><p>${L('只影响导出的文件，编辑器里的注释会完整保留','This changes exported files only, your editor keeps every comment')}</p><div class="export-modes">${[['all','保留全部注释','Keep all'],['selected','只保留我勾选的注释','Keep selected'],['none','不保留注释','Remove comments']].map(([id,zh,en])=>`<label><input type="radio" name="comment-mode" value="${id}" ${pref.mode===id?'checked':''}> ${L(zh,en)}</label>`).join('')}</div><section class="export-pick"><div class="detail-actions"><button class="btn btn-small btn-plain" data-all>${L('全选','Select all')}</button><button class="btn btn-small btn-plain" data-clear>${L('清空选择','Clear selection')}</button></div><div class="export-comments">${entries.map(c=>`<label><input type="checkbox" data-comment value="${E(c.id)}" ${pref.selected.includes(c.id)?'checked':''}><span><small>${E(c.file)} · ${E(c.section)}</small>${E(c.text)||'—'}</span></label>`).join('')||L('文件中还没有注释','No comments in these files')}</div></section><label class="export-remember"><input type="checkbox" data-remember ${pref.remember?'checked':''}> ${L('以后默认使用此选项，不再提示','Remember this choice and stop asking')}</label><p class="muted">${L('可在「设置 → 导出注释」重新打开提示或修改选择','Reopen the prompt from Settings → Export comments')}</p><div class="dialog-actions"><button class="btn btn-plain" data-cancel>${L('取消','Cancel')}</button><button class="btn btn-dark" data-confirm>${L('确认导出','Export')}</button></div>`;document.body.append(dialog);const sync=()=>dialog.querySelector('.export-pick').hidden=dialog.querySelector('input[name=comment-mode]:checked').value!=='selected';dialog.addEventListener('change',sync);sync();let finished=false;function finish(value){if(finished)return;finished=true;dialog.close();dialog.remove();resolve(value)}dialog.addEventListener('cancel',e=>{e.preventDefault();finish(null)});dialog.addEventListener('click',e=>{if(e.target.closest('[data-cancel]'))finish(null);if(e.target.closest('[data-all],[data-clear]'))for(const c of dialog.querySelectorAll('[data-comment]'))c.checked=!!e.target.closest('[data-all]');if(e.target.closest('[data-confirm]')){const value={mode:dialog.querySelector('input[name=comment-mode]:checked').value,selected:[...dialog.querySelectorAll('[data-comment]:checked')].map(c=>c.value),remember:dialog.querySelector('[data-remember]').checked};try{localStorage.setItem(key,JSON.stringify(value))}catch{root.toast?.(L('默认选项未能保存，请检查浏览器存储','Could not save this preference'))}finish(value)}});dialog.showModal()})}
async function files(input){const policy=await choose(input.filter(f=>typeof f.data==='string'));return policy?input.map(f=>({...f,data:typeof f.data==='string'?apply(f.data,f.name,policy):f.data})):null}
function reset(){const s=settings();s.remember=false;localStorage.setItem(key,JSON.stringify(s))}
root.RWExport={choose,files,settings,reset};
})(typeof window!=='undefined'?window:globalThis);
